diff --git a/source/endpoint-preview.ts b/source/endpoint-preview.ts
new file mode 100644
index 0000000..7cfdc0d
--- /dev/null
+++ b/source/endpoint-preview.ts
@@ -0,0 +1,121 @@
+import is from '@sindresorhus/is';
+import type {SearchParameters} from './core/options.js';
+
+export type EndpointChanges = {
+	protocol?: string;
+	hostname?: string;
+	host?: string;
+	port?: number | string;
+	pathname?: string;
+	search?: string;
+	searchParams?: string | SearchParameters | URLSearchParams;
+	/**
+	Legacy combined `pathname` and `search`, for example `/foo?bar=baz`.
+	*/
+	path?: string;
+};
+
+const normalizeProtocol = (protocol: string): string => protocol.endsWith(':') ? protocol : `${protocol}:`;
+
+const toSearchString = (searchParameters: string | SearchParameters | URLSearchParams): string => {
+	if (is.string(searchParameters) || searchParameters instanceof URLSearchParams) {
+		return new URLSearchParams(searchParameters).toString();
+	}
+
+	const parameters = new URLSearchParams();
+
+	for (const [key, value] of Object.entries(searchParameters)) {
+		if (value === undefined) {
+			continue;
+		}
+
+		parameters.append(key, value === null ? '' : String(value));
+	}
+
+	return parameters.toString();
+};
+
+const createBaseUrl = (origin: string, changes: EndpointChanges): URL => {
+	if (origin !== '') {
+		return new URL(origin);
+	}
+
+	const host = changes.host ?? changes.hostname;
+
+	if (changes.protocol === undefined || host === undefined) {
+		throw new TypeError('`protocol` and `host` or `hostname` are required when `origin` is empty');
+	}
+
+	return new URL(`${normalizeProtocol(changes.protocol)}//${host}`);
+};
+
+/**
+Compute the final URL string a request would use after applying `changes` to `origin`.
+
+The `changes` object is never modified.
+
+@param origin - The base URL. May be empty when `changes` provides `protocol` and `host` or `hostname`.
+@param changes - The URL related request options to apply.
+@returns The resulting URL as a string.
+*/
+export function endpointPreview(origin: string, changes: Readonly<EndpointChanges>): string {
+	assertUnambiguous(changes);
+
+	const url = createBaseUrl(origin, changes);
+
+	if (changes.protocol !== undefined) {
+		url.protocol = normalizeProtocol(changes.protocol);
+	}
+
+	if (changes.host !== undefined) {
+		url.host = changes.host;
+	}
+
+	if (changes.hostname !== undefined) {
+		url.hostname = changes.hostname;
+	}
+
+	if (changes.port !== undefined) {
+		url.port = String(changes.port);
+	}
+
+	if (changes.path !== undefined) {
+		const queryIndex = changes.path.indexOf('?');
+
+		if (queryIndex === -1) {
+			url.pathname = changes.path;
+			url.search = '';
+		} else {
+			url.pathname = changes.path.slice(0, queryIndex);
+			url.search = changes.path.slice(queryIndex);
+		}
+	}
+
+	if (changes.pathname !== undefined) {
+		url.pathname = changes.pathname;
+	}
+
+	if (changes.search !== undefined) {
+		url.search = changes.search;
+	}
+
+	if (changes.searchParams !== undefined) {
+		url.search = toSearchString(changes.searchParams);
+	}
+
+	return url.toString();
+}
+
+function assertUnambiguous(changes: Readonly<EndpointChanges>): void {
+	if (changes.path !== undefined) {
+		for (const key of ['pathname', 'search', 'searchParams'] as const) {
+			if (changes[key] !== undefined) {
+				throw new TypeError(`The \`path\` option cannot be used with the \`${key}\` option`);
+			}
+		}
+	}
+
+	if (changes.search !== undefined && changes.searchParams !== undefined) {
+		throw new TypeError('The `search` option cannot be used with the `searchParams` option');
+	}
+}
diff --git a/test/endpoint-preview.ts b/test/endpoint-preview.ts
new file mode 100644
index 0000000..bbe485e
--- /dev/null
+++ b/test/endpoint-preview.ts
@@ -0,0 +1,64 @@
+import test from 'ava';
+import {endpointPreview} from '../source/endpoint-preview.js';
+
+test('returns origin when there are no changes', t => {
+	t.is(endpointPreview('https://example.com/foo?bar=1', {}), 'https://example.com/foo?bar=1');
+});
+
+test('applies protocol, hostname, port, pathname and search', t => {
+	t.is(endpointPreview('http://example.com/old?x=1', {
+		protocol: 'https',
+		hostname: 'sindresorhus.com',
+		port: 8443,
+		pathname: '/new',
+		search: '?y=2',
+	}), 'https://sindresorhus.com:8443/new?y=2');
+});
+
+test('applies host including port', t => {
+	t.is(endpointPreview('https://example.com', {host: 'localhost:3000'}), 'https://localhost:3000/');
+});
+
+test('supports empty origin with protocol and host', t => {
+	t.is(endpointPreview('', {protocol: 'http:', host: 'localhost', port: '8080', pathname: '/api'}), 'http://localhost:8080/api');
+	t.is(endpointPreview('', {protocol: 'https', hostname: 'example.com'}), 'https://example.com/');
+});
+
+test('throws on empty origin without protocol or host', t => {
+	t.throws(() => endpointPreview('', {hostname: 'example.com'}), {instanceOf: TypeError});
+	t.throws(() => endpointPreview('', {protocol: 'https'}), {instanceOf: TypeError});
+});
+
+test('supports legacy path', t => {
+	t.is(endpointPreview('https://example.com/old?x=1', {path: '/foo?bar=baz'}), 'https://example.com/foo?bar=baz');
+	t.is(endpointPreview('https://example.com/old?x=1', {path: '/foo'}), 'https://example.com/foo');
+});
+
+test('supports searchParams', t => {
+	t.is(endpointPreview('https://example.com/?x=1', {searchParams: {a: 'b c', n: 1, empty: null, skip: undefined}}), 'https://example.com/?a=b+c&n=1&empty=');
+	t.is(endpointPreview('https://example.com/', {searchParams: new URLSearchParams([['k', 'a'], ['k', 'b']])}), 'https://example.com/?k=a&k=b');
+	t.is(endpointPreview('https://example.com/', {searchParams: 'a=1'}), 'https://example.com/?a=1');
+});
+
+test('does not modify changes', t => {
+	const searchParameters = new URLSearchParams({a: '1'});
+	const changes = {protocol: 'https', hostname: 'example.com', pathname: '/foo', searchParams: searchParameters};
+	const snapshot = {...changes};
+	endpointPreview('http://localhost', changes);
+	t.deepEqual(changes, snapshot);
+	t.is(searchParameters.toString(), 'a=1');
+});
+
+test('rejects ambiguous combinations', t => {
+	for (const key of ['pathname', 'search', 'searchParams'] as const) {
+		t.throws(() => endpointPreview('https://example.com', {path: '/foo', [key]: key === 'pathname' ? '/bar' : 'a=1'}), {
+			instanceOf: TypeError,
+			message: `The \`path\` option cannot be used with the \`${key}\` option`,
+		});
+	}
+
+	t.throws(() => endpointPreview('https://example.com', {search: '?a=1', searchParams: {b: 2}}), {
+		instanceOf: TypeError,
+		message: 'The `search` option cannot be used with the `searchParams` option',
+	});
+});
